import{z as A,x as n,o as i,c as m,q as l,j as o,D as E,d as e,s as p,S as s,b as r}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"离策略与重要性采样","description":"","frontmatter":{"title":"离策略与重要性采样","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/off-policy-importance-rl.md","filePath":"llm/off-policy-importance-rl.md","lastUpdated":1791063341000}'),B={name:"llm/off-policy-importance-rl.md"};function d(_,a,u,c,D,F){const t=n("Mermaid");return i(),m("div",null,[a[2]||(a[2]=l('<h1 id="离策略与重要性采样" tabindex="-1">离策略与重要性采样 <a class="header-anchor" href="#离策略与重要性采样" aria-label="Permalink to &quot;离策略与重要性采样&quot;">​</a></h1><div class="epigraph"><p>拿别人的轨迹评自己的策略，概率比率的连乘就是汇率；汇率连乘一千次，方差先于偏差爆炸。</p><footer>—— 据 Sutton &amp; Barto, 2018, §5.5；Precup, Sutton &amp; Singh, ICML 2000 整理</footer></div><p><a href="/llm/sarsa-q-learning">上一课</a>的离策略只到目标为止：Q 学习对 max 自举，数据仍由自己的行为策略生成。真正的离策略数据更彻底——重放的旧轨迹、人类演示、以及 LLM 训练里旧版本模型产出的 rollout——行为策略 \\(\\mu\\) 与被评估的策略 \\(\\pi\\) 不是同一个。缺口：不同分布下的直接平均估的是 \\(v_\\mu\\)，不是 \\(v_\\pi\\)。本课写重要性采样的校正，并钉住它的病根：方差随回合长度乘性增长。LLM 栏已有工程课<a href="/llm/truncated-importance-sampling">截断重要性采样</a>回答「截多少、截谁」；本课给它的统计骨架。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>数据按 \\(\\mu\\) 采样，想要 \\(v_\\pi\\)。轨迹在两个策略下的似然不同，校正系数是似然比</p> \\[\\rho(\\tau)=\\frac{\\Pr_\\pi(\\tau)}{\\Pr_\\mu(\\tau)}=\\prod_{k}\\frac{\\pi(a_k\\mid s_k)}{\\mu(a_k\\mid s_k)} . \\]<p>马尔可夫性让转移概率逐项相消，只剩动作比率——状态分布的偏移，全部由「这条动作序列在 \\(\\pi\\) 下本来就常见还是罕见」承担。校正之后做加权平均才是 \\(v_\\pi\\) 的估计；不加权，平均里混着 \\(\\mu\\) 的访问频率，策略一换答案就错。</p><p><span class="marginnote">术语翻译：行为策略 \\(\\mu\\) 是「实际出门采数据的那个人」，目标策略 \\(\\pi\\) 是「你想评估的那套决策规则」。重要性采样就是给 \\(\\mu\\) 的每条轨迹乘一个似然比「汇率」，把「\\(\\mu\\) 世界的平均回报」换算成「\\(\\pi\\) 世界的平均回报」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>普通重要性采样：\\(v_\\pi(s)\\approx\\frac{1}{N}\\sum_i \\rho^{(i)}G^{(i)}\\)，其中 \\(\\rho^{(i)}\\) 从 \\(s\\) 首次出现累乘到回合末。加权（自归一化）版本 \\(\\sum_i\\rho^{(i)}G^{(i)}\\big/\\sum_i\\rho^{(i)}\\) 有偏，但把比率的共同尺度消掉，方差通常更小。逐步（per-decision）版本（Precup 等 2000）把比率拆开，每个时步只用截至该步的累乘比率与对应奖励配对，方差进一步降。实现的底线只有一条：连乘必须搬到对数域做加法，回指数前再截断。</p>',10)),(i(),o(s,null,{default:E(()=>[p(t,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20MU%5B%22%CE%BC%20%E9%87%87%E6%A0%B7%E8%BD%A8%E8%BF%B9%20%CF%84%22%5D%20--%3E%20RHO%5B%22%E9%80%90%E6%AD%A5%E6%AF%94%E7%8E%87%20%CF%81_k%20%3D%20%CF%80(a_k%7Cs_k)%20%2F%20%CE%BC(a_k%7Cs_k)%22%5D%0A%20%20RHO%20--%3E%20LOG%5B%22%E5%AF%B9%E6%95%B0%E5%9F%9F%E7%B4%AF%E4%B9%98%22%5D%0A%20%20LOG%20--%3E%20EST%5B%22%E5%8A%A0%E6%9D%83%E5%B9%B3%E5%9D%87%EF%BC%8C%E4%BC%B0%E8%AE%A1%20v_%CF%80(s)%22%5D%0A%20%20LOG%20--%3E%20EXP%5B%22%E5%9B%9E%E5%90%88%E5%8F%98%E9%95%BF%EF%BC%9A%E4%BA%8C%E9%98%B6%E7%9F%A9%E4%B9%98%E6%80%A7%E5%A2%9E%E9%95%BF%22%5D%0A%20%20EXP%20--%3E%20CUT%5B%22%E6%88%AA%E6%96%AD%20%2F%20%E8%87%AA%E5%BD%92%E4%B8%80%E5%8C%96%EF%BC%9A%E5%81%8F%E7%BD%AE%E6%8D%A2%E6%96%B9%E5%B7%AE%22%5D%0A%20%20CUT%20--%3E%20ENG%5B%22%E5%B7%A5%E7%A8%8B%E6%88%AA%E6%B3%95%E8%A7%81%20llm%20%E6%A0%8F%E4%B8%93%E8%AF%BE%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[e("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"方差病根在二阶矩。每步比率的期望是 1，二阶矩不是：\\(\\mathbb{E}[\\rho_k^2]\\ge\\big(\\mathbb{E}[\\rho_k]\\big)^2=1\\)，而连乘把二阶矩也连乘——估计方差随回合长度乘性增长。数字口径：每步比率若只是 1.01，\\(1.01^{1000}\\approx2.1\\times10^4\\)；若每步 0.99，一千步后只剩 \\(4\\times10^{-5}\\)，有效样本条数坍缩到近零。这不是实现瑕疵，是估计量本身的性质：无偏与低方差在长回合上不可兼得，只能以偏置换方差。",-1)),(i(),o(s,null,{default:E(()=>[p(t,{id:"mermaid-33",class:"mermaid",graph:"flowchart%20TD%0A%20%20R1%5B%22%E6%AF%8F%E6%AD%A5%E6%AF%94%E7%8E%87%E6%9C%9F%E6%9C%9B%20%3D%201%22%5D%20--%3E%20R2%5B%22%E4%BD%86%E4%BA%8C%E9%98%B6%E7%9F%A9%20%E2%89%A5%201%22%5D%0A%20%20R2%20--%3E%20R3%5B%22%E8%BF%9E%E4%B9%98%E6%8A%8A%E6%96%B9%E5%B7%AE%E4%B9%9F%E8%BF%9E%E4%B9%98%22%5D%0A%20%20R3%20--%3E%20UP%5B%22%E6%AF%8F%E6%AD%A5%201.01%3A%20%E5%8D%83%E6%AD%A5%E5%90%8E%20%CF%81%E2%89%882.1%C3%9710%5E4%2C%20%E6%9D%83%E9%87%8D%E7%88%86%E7%82%B8%22%5D%0A%20%20R3%20--%3E%20DOWN%5B%22%E6%AF%8F%E6%AD%A5%200.99%3A%20%E5%8D%83%E6%AD%A5%E5%90%8E%20%CF%81%E2%89%884%C3%9710%5E-5%2C%20%E6%A0%B7%E6%9C%AC%E5%A4%B1%E6%95%88%22%5D%0A%20%20UP%20--%3E%20FIX%5B%22%E5%AF%B9%E6%95%B0%E5%9F%9F%E7%B4%AF%E5%8A%A0%20%2B%20%E6%88%AA%E6%96%AD%2F%E8%87%AA%E5%BD%92%E4%B8%80%E5%8C%96%22%5D%0A%20%20DOWN%20--%3E%20FIX%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p><span class="marginnote">直觉类比：连乘比率像连续兑换一千次货币——每次汇率哪怕只偏 1%，一千次后要么翻两万倍、要么只剩十万分之四。估计的「运气复利」就是这么支配方差的，所以截断不是工程偷懒，是对付复利的唯一办法。</span></p><p><span class="marginnote">半精度浮点的上界约 \\(6.5\\times10^4\\)：一千步、每步 1.01 的连乘已贴近上溢，每步 1.02 就冲到 \\(4\\times10^8\\)。对数域累加不是优化，是正确性。</span></p><p>与 Q 学习的分工要说清：Q 学习绕开重要性采样，是因为它不估 \\(v_\\pi\\)，直接对 \\(q_*\\) 自举；只要任务是「评估一个具体策略」或「校正控制方法的训练分布」，这类校正绕不开。LLM 的对照：一条几千 token 的完成，序列级比率是几千个 token 比率的连乘，不截断则方差在回合长度上指数回来；截断阈值、行为策略 logprob 的缓存、以及「截校正权重还是截近端代理」的取舍，<a href="/llm/truncated-importance-sampling">截断重要性采样</a>已按现场写成工程课，本课负责说明那些工程为何不是可选项。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>支撑条件不可协商：若某动作 \\(\\pi(a\\mid s)\\gt0\\) 而 \\(\\mu(a\\mid s)=0\\)，比率无定义（分母为零，这样的动作根本采不到），该区域的 \\(v_\\pi\\) 原则上不可估——没采过的东西没有数据，这是可辨识性而非技术细节。加权版本与逐步版本各自牺牲一点无偏性或一致性换方差，报结果时要写清用的是哪一种。马尔可夫性承担了转移项相消：部分可观测或状态定义不一致时，相消不成立，校正自带缺口。最后，回合越长、离得越远，纯重要性采样越像理论工具；活下来的是它的截断与近似变体——这句就是通往 LLM 栏工程课的桥。</p><p><span class="marginnote">常见误区：以为「无偏」就一定更好。普通 IS 无偏，但方差大到长回合上根本不可用；加权（自归一化）与逐步版本各自牺牲一点无偏性或一致性换方差。报实验时写清用的是哪一种估计量，比执着于无偏标签更实在。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>离策略评估靠轨迹似然比校正分布差；马尔可夫性使转移项相消，只剩动作比率。</li><li>普通 IS 无偏而方差最差；加权与逐步版本以偏置换方差。</li><li>方差随回合长度乘性增长；\\(\\mu\\) 覆盖 \\(\\pi\\) 的支撑是可辨识前提。</li><li>长序列上对数域累加与截断是正确性要求，不是优化偏好。</li><li>LLM 栏的工程课承接本课：阈值、缓存与截法的现场取舍。</li><li>出处：Sutton &amp; Barto 2018 §5.5；Precup, Sutton &amp; Singh, ICML 2000。</li></ul>',8))])}const f=A(B,[["render",d]]);export{C as __pageData,f as default};
